// Inventory + byte-compare two build output dirs.
// usage: node inventory.mjs <dirA> <dirB>
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

function walk(root, base = root, out = []) {
  for (const e of fs.readdirSync(root, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    const p = path.join(root, e.name);
    if (e.isDirectory()) walk(p, base, out);
    else if (e.isFile()) {
      const buf = fs.readFileSync(p);
      out.push({
        path: path.relative(base, p),
        bytes: buf.length,
        sha256: crypto.createHash('sha256').update(buf).digest('hex'),
      });
    }
  }
  return out;
}

const [a, b] = process.argv.slice(2);
const A = walk(a);
const B = walk(b);
const mapA = new Map(A.map((f) => [f.path, f]));
const mapB = new Map(B.map((f) => [f.path, f]));
const onlyA = A.filter((f) => !mapB.has(f.path)).map((f) => f.path);
const onlyB = B.filter((f) => !mapA.has(f.path)).map((f) => f.path);
const differing = A.filter((f) => mapB.has(f.path) && mapB.get(f.path).sha256 !== f.sha256).map((f) => ({
  path: f.path,
  bytesA: f.bytes,
  bytesB: mapB.get(f.path).bytes,
